// Throwaway RED probe (not committed): does Process.start() return while
// /proc/<pid>/comm still shows the parent's name (pre-exec window)?
// Mirrors test/env/bash_self_defense_test.dart AC2d killall fixture.
import 'dart:io';

Future<void> main(List<String> args) async {
  final rounds = args.isNotEmpty ? int.parse(args[0]) : 40;
  // Optional artificial load: N busy-loop shells widen the fork->exec window.
  final load = args.length > 1 ? int.parse(args[1]) : 0;
  final loaders = <Process>[];
  for (var i = 0; i < load; i++) {
    loaders.add(await Process.start('sh', ['-c', 'while :; do :; done']));
  }
  var misses = 0;
  for (var i = 0; i < rounds; i++) {
    final binDir = Directory.systemTemp.createTempSync('fa-probe-');
    final sleepBin =
        Process.runSync('sh', ['-c', 'command -v sleep']).stdout.trim();
    final victimPath = '${binDir.path}/fa_kl_271';
    File(sleepBin).copySync(victimPath);
    Process.runSync('chmod', <String>['755', victimPath]);
    final victim = await Process.start(victimPath, const ['271']);
    // FIRST thing after start: is the comm already the final binary name?
    final comm = Process.runSync('sh', ['-c', 'ps -o comm= -p ${victim.pid}'])
        .stdout
        .trim();
    final pgrep = Process.runSync('pgrep', ['-x', 'fa_kl_271']);
    final visible = pgrep.stdout.trim().split('\n').contains('${victim.pid}');
    if (!visible || comm != 'fa_kl_271') {
      misses++;
      stdout.writeln(
        'round $i: comm="$comm" pgrepVisible=$visible pid=${victim.pid}',
      );
    }
    victim.kill();
    binDir.deleteSync(recursive: true);
  }
  for (final l in loaders) {
    l.kill();
  }
  stdout.writeln('misses: $misses / $rounds');
}

// Throwaway RED probe v2 — inspect what ps/pgrep actually see right after
// Process.start returns, and how visibility evolves over the first ~50ms.
import 'dart:io';

void main(List<String> args) {
  final rounds = args.isNotEmpty ? int.parse(args[0]) : 10;
  var misses = 0;
  for (var i = 0; i < rounds; i++) {
    final binDir = Directory.systemTemp.createTempSync('fa-probe-');
    final sleepBin =
        Process.runSync('sh', ['-c', 'command -v sleep']).stdout.trim();
    final victimPath = '${binDir.path}/fa_kl_271';
    File(sleepBin).copySync(victimPath);
    Process.runSync('chmod', <String>['755', victimPath]);
    // ignore: unawaited_futures
    Process.start(victimPath, const ['271']).then((victim) {
      final p1 = Process.runSync('ps', ['-o', 'comm=', '-p', '${victim.pid}']);
      final g1 = Process.runSync('pgrep', ['-x', 'fa_kl_271']);
      final p2 = Process.runSync('ps', ['-o', 'comm=', '-p', '${victim.pid}']);
      final visible1 =
          g1.stdout.trim().split('\n').contains('${victim.pid}');
      final comm1 = p1.stdout.trim();
      final comm1rc = p1.exitCode;
      final comm1err = p1.stderr.trim();
      final comm2 = p2.stdout.trim();
      if (!visible1 || comm1 != 'fa_kl_271') {
        misses++;
        stdout.writeln(
          'round $i pid=${victim.pid}: comm="$comm1" (rc=$comm1rc err="$comm1err") '
          'pgrepVisible=$visible1 commAfterExtraSyscall="$comm2"',
        );
      }
      victim.kill();
      binDir.deleteSync(recursive: true);
    });
    // tiny spacing between rounds so rounds stay independent
    sleepSync(const Duration(milliseconds: 5));
  }
  sleepSync(const Duration(milliseconds: 300));
  stdout.writeln('misses: $misses / $rounds');
}

